package com.lebzlon.measurementtracker.repository; import com.lebzlon.measurementtracker.entity.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.domain.*; import java.util.*; public interface OcrTaskRepository extends JpaRepository<OcrTask,Long>{List<OcrTask> findByMeterUserOrderByCreatedAtDesc(User user); Optional<OcrTask> findByIdAndMeterUser(Long id, User user); Optional<OcrTask> findFirstByStatusOrderByCreatedAtAsc(OcrTaskStatus status);}